//! The outlines of the four boards and of the two sides of the Sky Islands,
//! traced from photographs of the printed ones: one polygon per region, in
//! the order of `smallworld_core`'s tables, in board units (1000 across).
//! Neighbouring outlines share their border points exactly, so the regions
//! fit together without gaps.

/// One region: where its tokens and icons go, and its outline as SVG
/// polygon points.
pub struct Shape {
    pub at: (i32, i32),
    pub points: &'static str,
}

/// A board's size and its regions.
pub struct Board {
    pub width: u32,
    pub height: u32,
    pub shapes: &'static [Shape],
}

/// A side of the Sky Islands.
pub fn sky(side: smallworld_core::Sky) -> &'static Board {
    match side {
        smallworld_core::Sky::Two => &SKY_TWO_BOARD,
        smallworld_core::Sky::Three => &SKY_THREE_BOARD,
    }
}

static SKY_TWO_BOARD: Board = Board { width: 1000, height: 570, shapes: SKY_TWO };
static SKY_THREE_BOARD: Board = Board { width: 1000, height: 540, shapes: SKY_THREE };

/// The board for `players` players (2 to 5).
pub fn board(players: usize) -> &'static Board {
    match players {
        2 => &BOARD_2,
        3 => &BOARD_3,
        4 => &BOARD_4,
        _ => &BOARD_5,
    }
}

static BOARD_2: Board = Board { width: 1000, height: 535, shapes: SHAPES_2 };
static BOARD_3: Board = Board { width: 1000, height: 535, shapes: SHAPES_3 };
static BOARD_4: Board = Board { width: 1000, height: 980, shapes: SHAPES_4 };
static BOARD_5: Board = Board { width: 1000, height: 973, shapes: SHAPES_5 };

